import { taskList as getTask } from '@/views/taskManage/mock.ts'



 export const taskList = () => getTask




export const generate = () => {
    return   getTask.map((item, index) => {
        return {
            id: item.id,
            name: item.name,
            startAddress: item.startAddress,
            endAddress: item.endAddress,
            startPoint: item.startPointLng+','+item.startPointLat,
            endPoint: item.endPointLng+','+item.endPointLat ,
            startTime: new Date().toISOString(),
            endTime: new Date().toISOString(),
            type: 'type' + (index % 3),
            amount: Math.floor(Math.random() * 1000),
            unit: '件',
            freight: Math.floor(Math.random() * 500),
            status: index % 2 === 0 ? '进行中' : '已完成'
        };
    })
}

export const getTaskDetail = (id) => {
    return generate().find(item => item.id === id)
}

export const paginate = <T>({ list, page, pageSize }: {list: T[], page: number, pageSize: number}): { data: T[], total: number } => {
    let lists = generate()
    const total = lists.length;
   // const count = Math.ceil(total / pageSize); // 总页数

    // 计算起始索引和结束索引
    const start = (page - 1) * pageSize;
    const end = start + pageSize;

    const data = lists.slice(start, end); // 当前页数据

    return {
        data,
        total
    };
};


/**
 * 在指定圆内生成随机点位（带车辆信息的对象格式）
 * @param center 圆心坐标 [经度, 纬度]
 * @param radius 半径（米）
 * @param num 生成数量
 * @returns {Object[]} 随机点位对象数组
 */
export const getMarker = (num = 20, center = [103.79516,30.085583], radius = 1000): {id: number; carNumber: string; lng: number; lat: number}[] => {
  const metersInDegrees = radius / 111319.5;
  const points: {id: number; carNumber: string; lng: number; lat: number}[] = [];

  for (let i = 0; i < num; i++) {
    const angle = Math.random() * 2 * Math.PI;
    const currentRadius = metersInDegrees * Math.sqrt(Math.random());

    const dx = currentRadius * Math.cos(angle);
    const dy = currentRadius * Math.sin(angle);

    // 计算坐标偏移
    const newLng = center[0] + dx / Math.cos(center[1] * Math.PI / 180);
    const newLat = center[1] + dy;

    points.push({
      id: i + 1, // 从1开始自增ID
      carNumber: `川A${ Math.floor(Math.random() * 900000) + 100000}`, // 生成CAR001格式编号
      lng: newLng,
      lat: newLat
    });
  }

  return points;
};

