// 抽稀算法实现（简化版）
const simplifyPath = (points, tolerance = 0.0001) => {
  const simplify = (pts, start, end, tol, result) => {
    if (end - start < 2) {
      result.push(pts[start]);
      return;
    }
    let maxDist = 0, maxIndex = start;
    for (let i = start + 1; i < end; i++) {
      const d = distance(pts[i], pts[start], pts[end]);
      if (d > maxDist) {
        maxDist = d;
        maxIndex = i;
      }
    }
    if (maxDist > tol) {
      simplify(pts, start, maxIndex, tol, result);
      simplify(pts, maxIndex, end, tol, result);
    } else {
      result.push(pts[start]);
    }
  };
  const result = [];
  simplify(points, 0, points.length - 1, tolerance, result);
  return result;

  // 计算点到直线的距离（简化为欧氏距离）
  function distance(p, p1, p2) {
    const A = p[0] - p1[0];
    const B = p[1] - p1[1];
    const C = p2[0] - p1[0];
    const D = p2[1] - p1[1];
    return Math.abs(A * D - B * C) / Math.sqrt(C * C + D * D);
  }
};


/**
 * 距离单位转换（米→公里）
 * @param meters 米为单位的距离数值
 * @param fixed 保留小数位数（默认2位）
 * @returns 格式化后的带单位距离（如：1.5km 或 800m）
 */
 const formatDistance = (meters, fixed = 2) => {
    if (meters < 1000) {
        return `${meters}米`;
    }
    return `${(meters / 1000).toFixed(fixed)}公里`;
};

